package ingest

import (
	"sync"

	"github.com/entirehq/entire-api/internal/pricing"
	"github.com/entirehq/entire-api/internal/store"
)

// loadPricing loads the embedded pricing table exactly once. A load error means a
// corrupt embedded asset — a build defect, not a runtime condition — so it is
// cached and surfaced by estimateCost as "no price" (nil cost) rather than
// crashing ingest: the pricing package's own unit tests guard the embedded table,
// so this never fires in a shipped binary.
//
// TODO(phase3): re-price job + live pricing pull. The raw per-model token buckets
// stay stored in the checkpoints.sessions JSONB (see parseSession), so when the
// pricing table changes a background job can re-run estimateCost over the
// "estimated" buckets and rewrite the cost columns without re-ingesting (a
// "reported" bucket is authoritative — the CLI priced it at the rates actually in
// force then — so a re-price would leave it alone). This loader would then read the
// refreshed table (via pricing.LoadTable overrides) instead of only the embedded one.
var loadPricing = sync.OnceValues(func() (*pricing.Table, error) {
	return pricing.LoadTable(nil)
})

// bucketCost prices one ingested token bucket (a model_usage entry, or a
// session's aggregate token_usage), returning the cost and the provenance label to
// stamp on it — (nil, "") when it cannot be priced at all.
//
// A cost the CLI already reported WINS over a server-side estimate. The CLI prices
// a session as its tokens are spent, against the rates that were actually in force
// at that moment; the platform has no price history, so re-deriving the cost of an
// old (or forked, or renamed) checkpoint from whatever table ships "today" would
// silently re-price it at rates that were never charged. Re-estimation stays as the
// FALLBACK for buckets that carry no reported cost — legacy checkpoints written
// before the CLI persisted one, and agent paths that never set it — which is also
// what makes a future re-price/rebuild job possible: the raw per-model token
// buckets stay stored in the checkpoints.sessions JSONB either way.
func bucketCost(model string, tu tokenUsage) (*float64, string) {
	if c := reportedCost(tu); c != nil {
		return c, store.CostSourceReported
	}
	if c := estimateCost(model, tu); c != nil {
		return c, store.CostSourceEstimated
	}
	return nil, ""
}

// reportedCost returns the cost the CLI computed for tu and persisted into the
// checkpoint metadata, or nil when there is nothing to trust: no cost_usd at all
// (nil means absent, NEVER a real 0), or a value the cost column can't hold.
//
// Any non-nil cost_usd here was computed by the CLI, never by us — this
// function only ever sees bytes parsed from the checkpoint's metadata.json,
// which we read, we never write. The CLI's own cost_source label ("reported"
// for an agent's self-reported billed cost, "estimated" for the CLI's
// token-based calculation, "mixed" when a bucket blends both) is CLI-internal
// provenance about *how* the CLI arrived at the number, not a signal for
// whether the platform should trust it: both "reported" and "estimated" were
// priced against the rates actually in force when the tokens were spent, which
// is exactly the authoritative-at-the-time value bucketCost's doc explains we
// want over a fresh re-estimate. Gating this on the literal string "reported"
// was a bug — it silently discarded the CLI's own token-based estimate (the
// common case for most agents) and re-priced it here instead, defeating the
// entire point of trusting the CLI. Ignore the label; trust the value.
// The returned pointer is a copy, so a later mutation can't reach back into the
// parsed payload.
func reportedCost(tu tokenUsage) *float64 {
	if tu.CostUSD == nil {
		return nil
	}
	// A non-finite/negative/over-range reported value is not a storable cost (it
	// would fault the NUMERIC(14,6) INSERT and poison-loop the consumer). Fall
	// through to the estimate rather than dropping the cost outright.
	if !store.ValidCostUSD(*tu.CostUSD) {
		return nil
	}
	c := *tu.CostUSD
	return &c
}

// estimateCost returns the platform-computed USD cost of tu's token counts under
// model, or nil when it cannot be priced: an empty/unknown model id (Lookup finds
// no rate — never guess, matching the CLI's "unknown model → nil cost" semantics),
// or a computed value outside the storable NUMERIC(14,6) range. The four token
// fields are priced cache-accurately (fresh input, cache-write, cache-read, output
// each at their own rate); this requires the per-model token breakdown, which the
// ingested metadata.json model_usage carries in full. It is the FALLBACK for
// buckets with no reported cost — see bucketCost.
func estimateCost(model string, tu tokenUsage) *float64 {
	tbl, err := loadPricing()
	if err != nil || tbl == nil {
		return nil
	}
	rate, ok := tbl.Lookup(model)
	if !ok {
		return nil
	}
	c := pricing.Estimate(rate, pricing.Usage{
		InputTokens:           tu.InputTokens,
		CacheCreationTokens:   tu.CacheCreationTokens,
		CacheCreation1hTokens: tu.CacheCreation1hTokens,
		CacheReadTokens:       tu.CacheReadTokens,
		OutputTokens:          tu.OutputTokens,
	})
	// Estimate can't produce NaN/Inf/negative from non-negative counts and
	// positive rates, but a pathologically large session could exceed the column
	// range; drop it (absence over an INSERT-faulting value) as ValidCostUSD guards.
	if !store.ValidCostUSD(c) {
		return nil
	}
	return &c
}

package pricing

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"os"
	"path/filepath"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/internal/flock"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/entireio/cli/internal/entireclient/userdirs"
)

// RemoteCache is the on-disk shape of the cached remote pricing table. It wraps
// the same fileSchema the embedded models/*.json files use — so validateRate and
// the schema_version contract are shared, not reimplemented — with the fetch
// bookkeeping the background refresh needs: FetchedAt drives the 24h refresh
// backoff, ETag drives conditional (If-None-Match) requests, SourceURL records
// where the table came from for diagnostics.
type RemoteCache struct {
	FetchedAt time.Time   `json:"fetched_at"`
	ETag      string      `json:"etag,omitempty"`
	SourceURL string      `json:"source_url,omitempty"`
	Doc       *fileSchema `json:"doc,omitempty"`
}

// remoteCacheFileName is the cache file basename. It lives beside the discovery
// caches under the per-user cache dir (userdirs.Cache()).
const remoteCacheFileName = "pricing_remote.json"

// remoteCachePath returns the absolute path of the remote pricing cache file.
// Path resolution goes through userdirs.Cache — the single implementation every
// cache consumer shares — so the remote pricing cache sits under ~/.cache/entire
// (or $XDG_CACHE_HOME/entire) with nodes.json and the other discovery caches.
func remoteCachePath() string {
	return filepath.Join(userdirs.Cache(), remoteCacheFileName)
}

// loadRemoteCache reads and parses the cache file. A missing file, a corrupt
// file, or any read error all return nil: the remote layer is purely additive,
// so "no usable cache" degrades to "embedded defaults only" and a damaged cache
// self-heals on the next successful refresh (which overwrites it atomically)
// rather than being rewritten here on the read path.
func loadRemoteCache() *RemoteCache {
	data, err := os.ReadFile(remoteCachePath()) // #nosec G304 -- path derived from userdirs, not user input
	if err != nil {
		return nil
	}
	var rc RemoteCache
	if err := json.Unmarshal(data, &rc); err != nil {
		return nil
	}
	return &rc
}

// LoadRemoteEntries returns the valid model rates from the cached remote pricing
// table, or nil when there is nothing usable. It is read-only and performs NO
// network I/O — the daily refresh (RefreshRemoteCache) is what populates the
// cache. It never errors: a missing or corrupt cache, an absent Doc, an
// unsupported schema_version, and individually invalid entries all degrade to
// "fewer (or zero) remote entries", so LoadPricingTable can layer whatever is
// valid on top of the embedded defaults without a failure path.
func LoadRemoteEntries(ctx context.Context) []ModelRate {
	rc := loadRemoteCache()
	if rc == nil || rc.Doc == nil {
		return nil
	}
	if rc.Doc.SchemaVersion != 1 {
		logging.Debug(ctx, "pricing: ignoring remote cache with unsupported schema_version",
			slog.Int("schema_version", rc.Doc.SchemaVersion))
		return nil
	}
	valid := make([]ModelRate, 0, len(rc.Doc.Models))
	for i := range rc.Doc.Models {
		m := rc.Doc.Models[i]
		if err := validateRate(m); err != nil {
			// Drop the single bad entry, keep the rest: one malformed row from
			// the remote table must not sink the whole merge.
			logging.Debug(ctx, "pricing: dropping invalid remote entry",
				slog.String("id", m.ID), slog.String("error", err.Error()))
			continue
		}
		valid = append(valid, m)
	}
	if len(valid) == 0 {
		return nil
	}
	return valid
}

// RemoteFetchedAt returns the time the remote pricing cache was last written, or
// the zero time when there is no cache. It exists for staleness diagnostics
// (the LoadPricingTable debug log and the manual refresh command).
func RemoteFetchedAt() time.Time {
	rc := loadRemoteCache()
	if rc == nil {
		return time.Time{}
	}
	return rc.FetchedAt
}

// RemoteURL is the default source for the remote pricing table. It is a var so
// tests can point it at an httptest server; the ENTIRE_PRICING_URL environment
// variable overrides it at fetch time for self-hosted setups.
var RemoteURL = "https://entire.io/pricing/v1/models.json"

const (
	// remoteRefreshInterval is the minimum cache age before a refresh is
	// attempted. Every fetch outcome — success, 304, or failure — resets
	// FetchedAt, so a broken endpoint is retried at most once per interval.
	remoteRefreshInterval = 24 * time.Hour
	// remoteMaxBytes caps the response body read (1 MiB), mirroring versioncheck.
	remoteMaxBytes = 1 << 20
)

// remoteFetchTimeout bounds the whole refresh request (dial + read), matching
// the version check's 2s budget so a slow endpoint never stalls a background
// worker. It is a var so tests can shrink it to exercise the timeout path fast.
var remoteFetchTimeout = 2 * time.Second

// Refresh outcomes reported by RefreshResult.Outcome.
const (
	refreshOutcomeUpdated     = "updated"      // 200 with a usable doc: Doc+ETag replaced.
	refreshOutcomeNotModified = "not-modified" // 304: prior Doc kept, FetchedAt bumped.
	refreshOutcomeUnchanged   = "unchanged"    // error/404/garbage: prior Doc kept, FetchedAt bumped.
	refreshOutcomeSkipped     = "skipped"      // throttled: fresh cache, no request made.
)

// RefreshResult summarizes what a refresh attempt did, for the manual
// `entire tokens pricing-refresh` report.
type RefreshResult struct {
	SourceURL string
	Outcome   string
	Entries   int
	FetchedAt time.Time
	ETag      string
}

// Staleness returns how old the cache is relative to now, or 0 when FetchedAt
// is unset.
func (r RefreshResult) Staleness() time.Duration {
	if r.FetchedAt.IsZero() {
		return 0
	}
	return time.Since(r.FetchedAt)
}

// remoteURL returns the effective source URL, honoring the ENTIRE_PRICING_URL
// override read at fetch time.
func remoteURL() string {
	if u := os.Getenv("ENTIRE_PRICING_URL"); u != "" {
		return u
	}
	return RemoteURL
}

// cacheStillFresh reports whether rc is recent enough, AND from the currently
// configured source, to skip a refresh. A nil rc is never fresh.
//
// The source check matters because ENTIRE_PRICING_URL can change between
// processes (self-hosted setups, testing): a cache that is "fresh" by the 24h
// clock but was fetched from the OLD source must not block a refresh against
// the NEW one, or the cache would keep serving the wrong source's prices under
// the new URL's name for up to 24h with no way to tell. Every "skip, still
// fresh" decision in this file must go through this one function so the source
// check can't drift out of sync between them.
func cacheStillFresh(rc *RemoteCache) bool {
	if rc == nil {
		return false
	}
	if rc.SourceURL != "" && rc.SourceURL != remoteURL() {
		return false
	}
	return time.Since(rc.FetchedAt) < remoteRefreshInterval
}

// ShouldRefresh reports whether the remote pricing cache is stale (older than
// the 24h interval), absent, or was fetched from a different source than the
// one currently configured. Trigger sites call it to gate a background refresh
// spawn so a fresh, same-source cache skips the work — and the spawn — entirely.
func ShouldRefresh() bool {
	return !cacheStillFresh(loadRemoteCache())
}

// RefreshRemoteCache fetches the remote pricing table and updates the local
// cache, honoring the 24h throttle. It is the entry point the detached
// __refresh_pricing worker calls. See refreshRemoteCache for the full contract.
func RefreshRemoteCache(ctx context.Context) error {
	_, err := refreshRemoteCache(ctx, false)
	return err
}

// RefreshRemoteCacheForce is RefreshRemoteCache without the freshness throttle:
// it always performs the network fetch and returns a RefreshResult describing
// the outcome. The manual `entire tokens pricing-refresh` command uses it.
func RefreshRemoteCacheForce(ctx context.Context) (RefreshResult, error) {
	return refreshRemoteCache(ctx, true)
}

// refreshRemoteCache is the shared implementation. It takes a cross-process
// flock for herd control, so several concurrently-spawned workers collapse to a
// single network request: the first takes the lock and refreshes, the rest take
// the lock, observe the freshly-written FetchedAt, and skip (unless force).
//
// Failure is absorbed, not surfaced: a network error, timeout, non-200 status,
// oversized/garbage body, or a doc that fails the schema/sanity check all keep
// the previous Doc+ETag and only bump FetchedAt — so a broken endpoint degrades
// to "keep serving the last good table" and is retried at most once per 24h. A
// 304 keeps the Doc and bumps FetchedAt. It returns an error only for a
// genuinely local failure (cache-dir create, lock, or write).
func refreshRemoteCache(ctx context.Context, force bool) (RefreshResult, error) {
	res := RefreshResult{SourceURL: remoteURL(), Outcome: refreshOutcomeSkipped}

	// Cheap pre-lock throttle: skip the lock entirely when the cache is fresh
	// and we are not forcing. The under-lock re-check below is the authoritative
	// herd-control guard; this just avoids lock contention on the common path.
	if !force && !ShouldRefresh() {
		fillResultFromCache(&res, loadRemoteCache())
		return res, nil
	}

	if err := os.MkdirAll(userdirs.Cache(), 0o700); err != nil {
		return res, fmt.Errorf("create cache dir: %w", err)
	}
	path := remoteCachePath()
	release, err := flock.Acquire(path + ".lock")
	if err != nil {
		return res, fmt.Errorf("lock remote pricing cache: %w", err)
	}
	defer release()

	// Re-read under the lock. If another process refreshed while we waited for
	// the lock, its FetchedAt is now fresh (and its source still matches) and we
	// skip the fetch (unless forced). This is what keeps a burst of spawned
	// workers to a single request.
	prev := loadRemoteCache()
	if !force && cacheStillFresh(prev) {
		fillResultFromCache(&res, prev)
		return res, nil
	}
	if prev == nil {
		prev = &RemoteCache{}
	}

	updated, outcome := fetchRemote(ctx, prev)
	if err := writeRemoteCache(path, updated); err != nil {
		return res, err
	}
	res.Outcome = outcome
	fillResultFromCache(&res, updated)
	return res, nil
}

// fillResultFromCache copies the reporting fields out of a cache snapshot.
func fillResultFromCache(res *RefreshResult, rc *RemoteCache) {
	if rc == nil {
		return
	}
	res.FetchedAt = rc.FetchedAt
	res.ETag = rc.ETag
	res.Entries = countValidEntries(rc.Doc)
}

// fetchRemote performs the conditional HTTP request and folds the outcome into a
// new RemoteCache derived from prev. Every outcome bumps FetchedAt. It never
// returns an error — the worst case is "keep prev's Doc+ETag", but only when
// prev is actually from the source about to be queried.
func fetchRemote(ctx context.Context, prev *RemoteCache) (*RemoteCache, string) {
	url := remoteURL()
	// prev may be from a DIFFERENT source (ENTIRE_PRICING_URL changed since it
	// was written — self-hosted setups, testing). Carrying its Doc/ETag over as
	// this fetch's fallback would, on any failure below, silently stamp the OLD
	// source's prices with the NEW source's URL and a fresh FetchedAt: a caller
	// reading the cache afterward has no way to tell it isn't actually serving
	// what SourceURL claims. Treat a source mismatch as "nothing to fall back
	// on" instead — a failure then correctly yields no usable remote data
	// (embedded defaults only) rather than mislabeled stale data.
	if prev.SourceURL != "" && prev.SourceURL != url {
		prev = &RemoteCache{}
	}
	out := &RemoteCache{
		FetchedAt: time.Now(),
		ETag:      prev.ETag,
		SourceURL: url,
		Doc:       prev.Doc,
	}

	ctx, cancel := context.WithTimeout(ctx, remoteFetchTimeout)
	defer cancel()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return out, refreshOutcomeUnchanged
	}
	req.Header.Set("Accept", "application/json")
	req.Header.Set("User-Agent", versioninfo.UserAgent())
	if prev.ETag != "" {
		req.Header.Set("If-None-Match", prev.ETag)
	}

	client := &http.Client{}
	resp, err := client.Do(req)
	if err != nil {
		return out, refreshOutcomeUnchanged
	}
	defer resp.Body.Close()

	if resp.StatusCode == http.StatusNotModified {
		return out, refreshOutcomeNotModified
	}
	if resp.StatusCode != http.StatusOK {
		return out, refreshOutcomeUnchanged
	}

	body, err := io.ReadAll(io.LimitReader(resp.Body, remoteMaxBytes))
	if err != nil {
		return out, refreshOutcomeUnchanged
	}
	var doc fileSchema
	if err := json.Unmarshal(body, &doc); err != nil {
		return out, refreshOutcomeUnchanged
	}
	if !remoteDocUsable(&doc) {
		return out, refreshOutcomeUnchanged
	}
	out.Doc = &doc
	out.ETag = resp.Header.Get("ETag")
	return out, refreshOutcomeUpdated
}

// remoteDocUsable is the sanity gate a freshly-fetched doc must pass before it
// replaces the cached table: the supported schema_version and at least one entry
// that survives validateRate. This mirrors LoadRemoteEntries' read-time contract
// so a doc that would contribute zero usable rates is never stored.
func remoteDocUsable(doc *fileSchema) bool {
	return countValidEntries(doc) > 0
}

// countValidEntries counts the entries in doc that pass validateRate under the
// supported schema_version; a nil or wrong-version doc counts zero.
func countValidEntries(doc *fileSchema) int {
	if doc == nil || doc.SchemaVersion != 1 {
		return 0
	}
	n := 0
	for i := range doc.Models {
		if validateRate(doc.Models[i]) == nil {
			n++
		}
	}
	return n
}

// writeRemoteCache writes rc atomically (temp + rename) so a concurrent reader
// never observes a half-written file.
func writeRemoteCache(path string, rc *RemoteCache) error {
	data, err := json.MarshalIndent(rc, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal remote pricing cache: %w", err)
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, 0o600); err != nil {
		return fmt.Errorf("write remote pricing cache tmp: %w", err)
	}
	if err := os.Rename(tmp, path); err != nil {
		_ = os.Remove(tmp)
		return fmt.Errorf("rename remote pricing cache: %w", err)
	}
	return nil
}

package pricing

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"log/slog"
	"path"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// ModelRate is the price of a single model, in USD per million tokens (MTok).
// CacheReadPerMTok and CacheWritePerMTok are optional: when nil, Estimate
// derives them from InputPerMTok using the Anthropic cache multipliers.
type ModelRate struct {
	// ID is the canonical model identifier (e.g. "claude-opus-4-8").
	ID string `json:"id"`
	// Provider is the vendor that serves the model (e.g. "anthropic").
	Provider string `json:"provider"`
	// Aliases are additional identifiers that resolve to this model. Each may
	// be a literal id or a shell-style glob (e.g. "claude-opus-4-8-*").
	Aliases []string `json:"aliases"`
	// InputPerMTok is the price of fresh (non-cached) input tokens per MTok.
	InputPerMTok float64 `json:"input_per_mtok"`
	// OutputPerMTok is the price of output tokens per MTok.
	OutputPerMTok float64 `json:"output_per_mtok"`
	// CacheReadPerMTok is the price of cache-read tokens per MTok, if set.
	CacheReadPerMTok *float64 `json:"cache_read_per_mtok"`
	// CacheWritePerMTok is the price of cache-write tokens per MTok, if set.
	CacheWritePerMTok *float64 `json:"cache_write_per_mtok"`
	// EffectiveDate is the ISO date the price took effect (informational).
	EffectiveDate string `json:"effective_date"`
}

// fileSchema is the on-disk shape of each embedded models/*.json file.
type fileSchema struct {
	SchemaVersion int         `json:"schema_version"`
	Models        []ModelRate `json:"models"`
}

// Table is a resolved set of model rates, keyed for lookup by id and alias.
type Table struct {
	models []ModelRate
	index  map[string]int
}

const (
	// AnthropicCacheReadMultiplier is the fraction of the input price charged
	// for cache-read tokens when a model omits an explicit cache-read rate.
	AnthropicCacheReadMultiplier = 0.1
	// AnthropicCacheWriteMultiplier is the multiple of the input price charged
	// for cache-write tokens when a model omits an explicit cache-write rate.
	AnthropicCacheWriteMultiplier = 1.25
	// AnthropicCacheWrite1hMultiplier is the multiple of the input price charged
	// for 1-hour-TTL cache-write tokens (vs 1.25x for the 5-minute default).
	AnthropicCacheWrite1hMultiplier = 2.0
)

// LoadTable parses every embedded pricing file, validates each entry, then
// layers the given overrides on top: an override whose id matches an existing
// entry replaces it, otherwise it is appended. Overrides are validated too. A
// nil or empty overrides slice yields the embedded defaults unchanged.
func LoadTable(overrides []ModelRate) (*Table, error) {
	entries, err := fs.ReadDir(modelsFS, "models")
	if err != nil {
		return nil, fmt.Errorf("reading embedded pricing models: %w", err)
	}

	t := &Table{index: make(map[string]int)}
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		data, err := modelsFS.ReadFile(path.Join("models", e.Name()))
		if err != nil {
			return nil, fmt.Errorf("reading embedded pricing model %s: %w", e.Name(), err)
		}
		var schema fileSchema
		if err := json.Unmarshal(data, &schema); err != nil {
			return nil, fmt.Errorf("parsing pricing model %s: %w", e.Name(), err)
		}
		for i := range schema.Models {
			m := schema.Models[i]
			if err := validateRate(m); err != nil {
				return nil, fmt.Errorf("invalid pricing entry in %s: %w", e.Name(), err)
			}
			t.add(m)
		}
	}

	for i := range overrides {
		o := overrides[i]
		if err := validateRate(o); err != nil {
			return nil, fmt.Errorf("invalid pricing override: %w", err)
		}
		t.add(o)
	}

	return t, nil
}

// ValidOverrides returns the subset of overrides that pass validation, dropping
// and logging each invalid entry rather than failing on it. It mirrors
// LoadRemoteEntries so a single malformed user override in .entire/settings.json
// cannot sink the whole pricing table: LoadTable hard-errors on any invalid
// override, and LoadPricingTable would then discard the entire table and disable
// cost estimation. Callers pre-filter user overrides through this before handing
// them to LoadTable. Order is preserved so LoadTable's last-writer-wins layering
// is unaffected. A nil/empty input yields nil.
func ValidOverrides(ctx context.Context, overrides []ModelRate) []ModelRate {
	if len(overrides) == 0 {
		return nil
	}
	valid := make([]ModelRate, 0, len(overrides))
	for i := range overrides {
		o := overrides[i]
		if err := validateRate(o); err != nil {
			logging.Warn(ctx, "pricing: dropping invalid pricing override entry",
				slog.String("id", o.ID), slog.String("error", err.Error()))
			continue
		}
		valid = append(valid, o)
	}
	return valid
}

// add inserts m, replacing any existing entry that shares its id. Ids are
// canonicalized (trimmed, lower-cased) for the index key so that an override
// whose id differs only in case or surrounding whitespace replaces the builtin
// entry instead of appending a phantom duplicate. The stored id is trimmed. When
// an override omits aliases, provider, or cache rates, it inherits them from
// the replaced entry so a minimal price override (id + input/output only)
// keeps resolving the dated and provider-prefixed spellings the embedded
// entry covered and keeps the provider's cache economics.
func (t *Table) add(m ModelRate) {
	m.ID = strings.TrimSpace(m.ID)
	key := strings.ToLower(m.ID)
	if idx, ok := t.index[key]; ok {
		prev := t.models[idx]
		if len(m.Aliases) == 0 {
			m.Aliases = prev.Aliases
		}
		if strings.TrimSpace(m.Provider) == "" {
			m.Provider = prev.Provider
		}
		if m.CacheReadPerMTok == nil {
			m.CacheReadPerMTok = prev.CacheReadPerMTok
		}
		if m.CacheWritePerMTok == nil {
			m.CacheWritePerMTok = prev.CacheWritePerMTok
		}
		t.models[idx] = m
		return
	}
	t.index[key] = len(t.models)
	t.models = append(t.models, m)
}

// Lookup resolves a model identifier to its rate. It first tries an exact match
// against a known id, then falls back to normalized (lower-cased, trimmed)
// matching against ids and aliases, where an alias may be a shell-style glob.
// It performs no implicit model-family fallback; an unknown model returns
// (ModelRate{}, false).
//
// Matching is attempted against the normalized query and, when the query carries
// a bracketed long-context suffix such as "[1m]", the same query with that
// suffix removed. path.Match treats "[...]" as a character class, so a literal
// "[1m]" alias would never match; normalizing on the query side sidesteps that
// trap and lets a bare id like "claude-fable-5[1m]" (the form Claude Code emits)
// resolve to "claude-fable-5", which bills at the same base rate.
func (t *Table) Lookup(model string) (ModelRate, bool) {
	norm := strings.ToLower(strings.TrimSpace(model))
	if norm == "" {
		return ModelRate{}, false
	}

	// The index is keyed by canonical (trimmed, lower-cased) id, so the fast
	// path must probe with the same canonicalization the query was normalized to.
	if idx, ok := t.index[norm]; ok {
		return t.models[idx], true
	}

	candidates := []string{norm}
	if base := stripLongContextSuffix(norm); base != norm && base != "" {
		candidates = append(candidates, base)
	}

	for i := range t.models {
		r := t.models[i]
		id := strings.ToLower(r.ID)
		for _, q := range candidates {
			if id == q {
				return r, true
			}
		}
		for _, alias := range r.Aliases {
			na := strings.ToLower(strings.TrimSpace(alias))
			if na == "" {
				continue
			}
			isGlob := strings.ContainsAny(na, "*?[")
			for _, q := range candidates {
				if isGlob {
					if ok, err := path.Match(na, q); err == nil && ok {
						return r, true
					}
					continue
				}
				if na == q {
					return r, true
				}
			}
		}
	}

	return ModelRate{}, false
}

// stripLongContextSuffix removes a trailing bracketed suffix such as the "[1m]"
// long-context marker that Claude Code appends to model ids (e.g.
// "claude-fable-5[1m]"). It returns s unchanged when there is no such suffix.
func stripLongContextSuffix(s string) string {
	if strings.HasSuffix(s, "]") {
		if i := strings.IndexByte(s, '['); i >= 0 {
			return s[:i]
		}
	}
	return s
}

// Estimate returns the USD cost of u under rate r. Fresh input, cache-read,
// cache-write, and output tokens are each priced separately and summed.
//
// The nil-cache-rate fallbacks are provider-aware. The
// AnthropicCacheReadMultiplier (0.1x input) and AnthropicCacheWriteMultiplier
// (1.25x input) encode Anthropic economics, so they apply only when Provider is
// "anthropic" (case-insensitive). For any other provider a missing cache-read or
// cache-write rate falls back to the full input rate (1.0x) — billing cached
// tokens as normal input, which never undercharges. In practice the non-Anthropic
// embedded tables carry explicit cache rates, so this fallback is a safety net.
func Estimate(r ModelRate, u types.TokenUsage) float64 {
	isAnthropic := strings.EqualFold(strings.TrimSpace(r.Provider), "anthropic")

	crRate := r.InputPerMTok
	if isAnthropic {
		crRate = AnthropicCacheReadMultiplier * r.InputPerMTok
	}
	if r.CacheReadPerMTok != nil {
		crRate = *r.CacheReadPerMTok
	}
	cwRate := r.InputPerMTok
	if isAnthropic {
		cwRate = AnthropicCacheWriteMultiplier * r.InputPerMTok
	}
	if r.CacheWritePerMTok != nil {
		cwRate = *r.CacheWritePerMTok
	}

	cw1hRate := cwRate
	if isAnthropic && r.CacheWritePerMTok == nil {
		cw1hRate = AnthropicCacheWrite1hMultiplier * r.InputPerMTok
	}
	cw1h := u.CacheCreation1hTokens
	if cw1h < 0 {
		cw1h = 0
	}
	if cw1h > u.CacheCreationTokens {
		cw1h = u.CacheCreationTokens
	}
	cw5m := u.CacheCreationTokens - cw1h

	input := float64(u.InputTokens) * r.InputPerMTok
	cacheRead := float64(u.CacheReadTokens) * crRate
	cacheWrite := float64(cw5m)*cwRate + float64(cw1h)*cw1hRate
	output := float64(u.OutputTokens) * r.OutputPerMTok

	return (input + cacheRead + cacheWrite + output) / 1e6
}

// validateRate rejects entries that would make an estimate meaningless: a
// missing id or a non-positive input/output rate. Explicit cache rates, when
// present, must not be negative.
func validateRate(r ModelRate) error {
	if strings.TrimSpace(r.ID) == "" {
		return errors.New("model id must not be empty")
	}
	if r.InputPerMTok <= 0 {
		return fmt.Errorf("model %q: input_per_mtok must be positive, got %v", r.ID, r.InputPerMTok)
	}
	if r.OutputPerMTok <= 0 {
		return fmt.Errorf("model %q: output_per_mtok must be positive, got %v", r.ID, r.OutputPerMTok)
	}
	if r.CacheReadPerMTok != nil && *r.CacheReadPerMTok < 0 {
		return fmt.Errorf("model %q: cache_read_per_mtok must not be negative, got %v", r.ID, *r.CacheReadPerMTok)
	}
	if r.CacheWritePerMTok != nil && *r.CacheWritePerMTok < 0 {
		return fmt.Errorf("model %q: cache_write_per_mtok must not be negative, got %v", r.ID, *r.CacheWritePerMTok)
	}
	for _, alias := range r.Aliases {
		if strings.TrimSpace(alias) == "" {
			return fmt.Errorf("model %q: alias must not be empty or whitespace", r.ID)
		}
		// A glob alias with malformed metacharacters (e.g. an unterminated "[")
		// would silently never match at Lookup time (path.Match swallows
		// ErrBadPattern there), so reject it up front where it is a config error.
		if strings.ContainsAny(alias, "*?[") {
			if _, err := path.Match(alias, "probe"); errors.Is(err, path.ErrBadPattern) {
				return fmt.Errorf("model %q: invalid alias glob %q: %w", r.ID, alias, err)
			}
		}
	}
	return nil
}

/**
 * Types + pure transform for the public pricing catalog served at
 * GET /pricing/v1/models.json (see ../../routes/pricing.ts) and regenerated by
 * scripts/generate-pricing-catalog.ts.
 *
 * This is what entireio/cli's daily pricing-refresh mechanism
 * (cmd/entire/cli/pricing/remote.go, PR #1763) fetches and ETag-conditionally
 * caches. Keep this shape byte-for-byte in sync with that Go `fileSchema` /
 * `ModelRate` struct pair — the CLI hard-rejects any `schema_version` other
 * than 1, and only tolerates individual malformed entries (drops them, keeps
 * the rest), not a malformed top level.
 */

export const PRICING_SCHEMA_VERSION = 1

export interface ModelRate {
  id: string
  provider: string
  aliases: string[]
  input_per_mtok: number
  output_per_mtok: number
  cache_read_per_mtok: number | null
  cache_write_per_mtok: number | null
  effective_date: string
}

export interface PricingCatalog {
  schema_version: typeof PRICING_SCHEMA_VERSION
  models: ModelRate[]
}

/** The slice of models.dev's `api.json` shape (https://models.dev/api.json) that we read. */
export interface ModelsDevCost {
  input?: number
  output?: number
  cache_read?: number
  cache_write?: number
}

export interface ModelsDevModel {
  id?: string
  cost?: ModelsDevCost
  // last_updated deliberately not modeled here — see transformModel below for why
  // we never read it.
}

export interface ModelsDevProvider {
  models?: Record<string, ModelsDevModel>
}

export type ModelsDevPayload = Record<string, ModelsDevProvider>

export class PricingSourceError extends Error {}

const MIN_TOTAL_MODELS = 50
const REQUIRED_PROVIDER_KEYS = ["anthropic", "openai"] as const

/**
 * models.dev is keyed by (provider, model), and hundreds of its "provider"
 * entries are resale/gateway/cloud-hosting products (OpenRouter, Requesty,
 * Azure, Amazon Bedrock, Vertex, ...) that RE-LIST the same first-party model
 * id under their own provider key — often at a different, reseller-marked-up
 * or -down price. Our own output is flat-keyed by id (matching the CLI's
 * `ModelRate`/`Table.add`, which is last-write-wins keyed on
 * `strings.ToLower(id)` — cmd/entire/cli/pricing/table.go:140-158), so an
 * unfiltered mirror of models.dev produces hundreds of id collisions
 * (measured: 896 duplicate ids across 172 providers, 563 with DIVERGENT
 * prices). Concretely: `claude-sonnet-4-6` is re-listed under >15 gateway
 * providers, some at a materially different price than Anthropic's own
 * ($3/$15 per Mtok) — and the CLI's cache-rate multipliers additionally key
 * off `provider == "anthropic"` (table.go:247-265), so a collision that
 * resolves to the wrong provider corrupts BOTH the base rate and the
 * cache-rate math, in an unpredictable direction.
 *
 * We avoid this at the root by only transforming entries from providers that
 * are themselves the model's creator (the actual vendor), never a
 * reseller/router/cloud-hosting front for someone else's model. This is a
 * deliberately small, hand-curated, conservative list — completeness lost by
 * being conservative is far cheaper than a mispriced/mislabeled entry. Cloud
 * hosting umbrellas that carry a MIX of their own and third-party models
 * (amazon-bedrock, google-vertex, azure, azure-cognitive-services) are
 * excluded entirely rather than partially, for the same reason: also true of
 * pure inference-hosting resellers of open-weight models (groq, togetherai,
 * fireworks-ai, deepinfra, cerebras, nvidia, watsonx, ...), which own no
 * models of their own.
 */
export const FIRST_PARTY_PROVIDER_KEYS: ReadonlySet<string> = new Set([
  "anthropic",
  "openai",
  "google",
  "xai",
  "meta",
  "mistral",
  "cohere",
  "deepseek",
  "alibaba",
  "moonshotai",
  "zhipuai",
  "minimax",
  "perplexity",
])

/**
 * Even inside an allowlisted first-party provider, a handful of entries are
 * known to actually be a THIRD PARTY's model re-hosted through that
 * provider's own marketplace (e.g. Alibaba Cloud Model Studio also serves a
 * few non-Alibaba models under the plain "alibaba" provider key). Verified
 * against the live models.dev payload on 2026-08-10: "glm-5.2" under
 * "alibaba" is a re-host of Zhipu AI's own (canonical) "glm-5.2" — keeping
 * both would silently collide. Listed explicitly, one pair at a time, rather
 * than solved with a heuristic, so each exclusion has a stated reason and a
 * paper trail. assertNoDuplicateModelIds() below is the backstop for
 * anything not (yet) listed here.
 */
const KNOWN_THIRD_PARTY_LISTINGS: ReadonlySet<string> = new Set([
  // Re-host of zhipuai's own "glm-5.2" — see comment above.
  "alibaba:glm-5.2",
])

function isKnownThirdPartyListing(providerKey: string, modelKey: string): boolean {
  return KNOWN_THIRD_PARTY_LISTINGS.has(`${providerKey}:${modelKey}`)
}

/**
 * Fails loudly if any two surviving entries share a (case-insensitive) id —
 * exactly the condition the CLI's id-keyed, last-write-wins Table.add() would
 * otherwise resolve silently and unpredictably (table.go:140-158). This is
 * the backstop for FIRST_PARTY_PROVIDER_KEYS/KNOWN_THIRD_PARTY_LISTINGS: if
 * models.dev data drifts (a newly-added first-party provider collides with
 * an existing one, or a cloud marketplace adds another re-host we haven't
 * excluded yet), generation must stop and demand an explicit decision rather
 * than let two different prices silently fight over one id.
 */
export function assertNoDuplicateModelIds(catalog: PricingCatalog): void {
  const providersById = new Map<string, string[]>()
  for (const model of catalog.models) {
    const key = model.id.toLowerCase()
    const providers = providersById.get(key) ?? []
    providers.push(model.provider)
    providersById.set(key, providers)
  }

  const duplicates = [...providersById.entries()].filter(([, providers]) => providers.length > 1)
  if (duplicates.length > 0) {
    const detail = duplicates
      .slice(0, 10)
      .map(([id, providers]) => `"${id}" (${providers.join(", ")})`)
      .join("; ")
    throw new PricingSourceError(
      `pricing catalog has ${duplicates.length} duplicate model id(s) after first-party filtering ` +
        `— refusing to write a catalog where a last-write-wins consumer could pick either price: ${detail}`,
    )
  }
}

/**
 * Sanity-gates the RAW models.dev payload before any transform runs. Catches
 * a truncated fetch, an empty/garbage body, or an upstream schema change
 * loudly and early, rather than silently writing a near-empty catalog.
 * Mirrors the spirit of Pi's `validateBundle` guard (packages/ai/scripts/
 * generate-models.ts), trimmed to just what this generator needs.
 */
export function assertSaneModelsDevPayload(payload: ModelsDevPayload): void {
  const providerKeys = Object.keys(payload)
  const totalModels = providerKeys.reduce(
    (sum, key) => sum + Object.keys(payload[key]?.models ?? {}).length,
    0,
  )

  if (totalModels < MIN_TOTAL_MODELS) {
    throw new PricingSourceError(
      `models.dev payload has only ${totalModels} model(s) across ${providerKeys.length} provider(s) ` +
        `(need >= ${MIN_TOTAL_MODELS}) — refusing to write a garbage pricing catalog`,
    )
  }

  const missingProviders = REQUIRED_PROVIDER_KEYS.filter((key) => !(key in payload))
  if (missingProviders.length > 0) {
    throw new PricingSourceError(
      `models.dev payload is missing required provider key(s): ${missingProviders.join(", ")} — ` +
        `refusing to write a garbage pricing catalog`,
    )
  }
}

/**
 * Sanity-gates the TRANSFORMED catalog, after per-entry filtering. Catches
 * the case where the raw payload looked fine but every anthropic/openai
 * entry happened to be unpriceable (see transformModel).
 */
export function assertSaneCatalog(catalog: PricingCatalog): void {
  if (catalog.models.length < MIN_TOTAL_MODELS) {
    throw new PricingSourceError(
      `transformed pricing catalog has only ${catalog.models.length} model(s) ` +
        `(need >= ${MIN_TOTAL_MODELS}) — refusing to write a garbage pricing catalog`,
    )
  }

  const providers = new Set(catalog.models.map((m) => m.provider))
  const missingProviders = REQUIRED_PROVIDER_KEYS.filter((key) => !providers.has(key))
  if (missingProviders.length > 0) {
    throw new PricingSourceError(
      `transformed pricing catalog has zero priced models for required provider(s): ` +
        `${missingProviders.join(", ")} — refusing to write a garbage pricing catalog`,
    )
  }
}

/**
 * Transforms one models.dev model entry into a ModelRate, or returns null to
 * drop it. We DROP (rather than fabricate a 0) any model missing a usable
 * cost.input/cost.output — a silently-zeroed price reads as "this model is
 * free," which is worse than the model being absent from the catalog. The
 * CLI's own per-entry validation exists to catch malformed entries it can
 * see; it's not a substitute for us feeding it invented numbers.
 */
export function transformModel(
  providerKey: string,
  modelKey: string,
  model: ModelsDevModel,
  ingestDate: string,
): ModelRate | null {
  const id = model.id || modelKey
  const cost = model.cost
  if (!id || !providerKey || !cost) return null
  if (typeof cost.input !== "number" || typeof cost.output !== "number") return null
  // <= 0, not < 0: the CLI's own validateRate (table.go:292-297) already
  // rejects InputPerMTok/OutputPerMTok <= 0 on the receiving end, so a
  // zero-priced entry can never reach a user as real pricing — this is pure
  // payload hygiene (fewer wasted bytes, no misleading "N models" count),
  // not a correctness fix.
  if (cost.input <= 0 || cost.output <= 0) return null

  return {
    id,
    provider: providerKey,
    aliases: [],
    input_per_mtok: cost.input,
    output_per_mtok: cost.output,
    cache_read_per_mtok: typeof cost.cache_read === "number" ? cost.cache_read : null,
    cache_write_per_mtok: typeof cost.cache_write === "number" ? cost.cache_write : null,
    // Ingest-time date — deliberately NOT models.dev's own `last_updated`.
    // `last_updated` is bumped by any edit to a hand-authored provider entry
    // (new capability flag, typo fix, ...), not specifically by a price
    // change, and models.dev's sync docs give no guarantee it tracks cost
    // edits in particular. Ingest date is honest about what we actually
    // know: this price was in effect as of (at latest) this date.
    effective_date: ingestDate,
  }
}

/**
 * Builds the full catalog from a models.dev payload, restricted to
 * FIRST_PARTY_PROVIDER_KEYS (see comment there for why). Call
 * assertSaneModelsDevPayload on the raw payload first. Throws
 * (assertNoDuplicateModelIds) if any two surviving entries collide on id —
 * always call this rather than hand-rolling the loop, so that guard can't be
 * bypassed.
 */
export function buildPricingCatalog(payload: ModelsDevPayload, ingestDate: string): PricingCatalog {
  const models: ModelRate[] = []
  for (const providerKey of Object.keys(payload)) {
    if (!FIRST_PARTY_PROVIDER_KEYS.has(providerKey)) continue
    const providerModels = payload[providerKey]?.models ?? {}
    for (const modelKey of Object.keys(providerModels)) {
      if (isKnownThirdPartyListing(providerKey, modelKey)) continue
      const rate = transformModel(providerKey, modelKey, providerModels[modelKey], ingestDate)
      if (rate) models.push(rate)
    }
  }
  const catalog: PricingCatalog = { schema_version: PRICING_SCHEMA_VERSION, models }
  assertNoDuplicateModelIds(catalog)
  return catalog
}

/** Ingest-time UTC ISO date (e.g. "2026-08-10"), used as every entry's effective_date. */
export function todayUTC(now: Date = new Date()): string {
  return now.toISOString().slice(0, 10)
}

