// Canonical, single-entry cache key — the public route has no query params
// that vary the response, but a synthetic internal-looking key (matching
// clusters-cache.ts / trail-attachment-cache.ts) avoids ever accidentally
// fragmenting on an incidental header/param Cloudflare's default request-URL
// keying might otherwise key on.
const CACHE_ORIGIN = "https://entire-api-pricing.internal"
const TTL_SECONDS = 3_600

export function pricingCacheKey(): Request {
  return new Request(`${CACHE_ORIGIN}/models.json`)
}

// The narrow slice of the Cache interface this route actually uses — mirrors
// ClustersCache / TrailAttachmentCache's own pattern of a small typed wrapper
// rather than depending on the full W3C Cache surface, and lets a test inject
// a plain in-memory fake without needing the Workers-pool runtime that a real
// `caches.default` requires (unavailable under plain node/vitest — see
// resolve-home.test.ts's identical note).
export interface PricingEdgeCache {
  match(req: Request): Promise<Response | undefined>
  put(req: Request, res: Response): Promise<void>
}

// null when the Cache API is unavailable (the Node test runtime has no
// `caches` global — matches trailAttachmentCache()'s same guard), so serving
// degrades to always fetching from entire-api instead of throwing.
export function pricingEdgeCache(): PricingEdgeCache | null {
  if (typeof caches === "undefined") return null
  return caches.default
}

export function createPricingRoutes(cache: PricingEdgeCache | null = pricingEdgeCache()) {
  const pricingRoutes = new Hono<{ Bindings: Env; Variables: Variables }>()

  pricingRoutes.get("/v1/models.json", etag(), async (c) => {
    if (cache) {
      const hit = await cache.match(pricingCacheKey())
      // A Response from the Cache API has IMMUTABLE headers (Cloudflare's
      // documented behavior) — returning it as-is crashes the etag()
      // middleware above, which sets an ETag header on whatever the handler
      // returns, with "TypeError: Can't modify immutable headers". Wrapping
      // it in a new Response (the documented workaround) makes a genuinely
      // mutable copy. Caught by a real Miniflare-backed e2e test — the

Exit code 1
      // mutable copy. Caught by a real Miniflare-backed e2e test — the
      // in-memory fake cache used elsewhere doesn't reproduce this, since a
      // plain object's headers are never actually immutable.
      if (hit) return new Response(hit.body, hit)
    }

    if (!c.env.ENTIRE_API_PRICING_BASE_URL) {
      return c.json({ error: "Pricing catalog is not configured" }, 502)
    }

    const upstreamURL = new URL("/api/v1/pricing/models.json", c.env.ENTIRE_API_PRICING_BASE_URL)
    let upstream: Response
    try {
      upstream = await fetch(upstreamURL, { headers: { Accept: "application/json" } })
    } catch (error) {
      console.error("pricing: entire-api catalog fetch failed", error)
      return c.json({ error: "Pricing catalog upstream unreachable" }, 502)
    }
    if (!upstream.ok) {
      console.error("pricing: entire-api catalog returned", upstream.status)
      return c.json({ error: "Pricing catalog upstream error" }, 502)
    }

    let catalog: unknown
    try {
      catalog = await upstream.json()
    } catch (error) {
      console.error("pricing: entire-api catalog response was not valid JSON", error)
      return c.json({ error: "Pricing catalog upstream returned malformed data" }, 502)
    }

    // Also respected by any client/proxy downstream of Cloudflare that honors
    // standard HTTP caching, and read by cache.put() below to set the edge TTL.
    c.header("Cache-Control", `public, max-age=${TTL_SECONDS}`)
    const res = c.json(catalog)

    if (cache) {
      // Fire-and-forget: the edge write must never add latency to this
      // response. Only a genuinely successful catalog reaches here — none of
      // the error responses above are ever cached.
      await runInBackground(c, () =>
        (cache as PricingEdgeCache).put(pricingCacheKey(), res.clone()),
      )
    }

    return res
  })

  return pricingRoutes
}

