// pricingCatalogSchemaVersion is the on-the-wire schema version every consumer
// (the CLI's remote-catalog reader, entire.io's pass-through proxy) agrees on.
// Bump only in lockstep with every consumer.
const pricingCatalogSchemaVersion = 1

// pricingCatalogModel is the WIRE shape of one model rate: camelCase per
// CASING-001, which governs Entire-defined JSON API fields.
//
// It is deliberately a separate type from pricing.ModelRate rather than a set
// of tags on it, because ModelRate's own snake_case tags are a STORAGE format
// with two other consumers that must not move: this repo's embedded
// models/*.json build assets, and — in the CLI, which shares the struct — the
// user-facing `pricing.models` override block in .entire/settings.json.
// Re-casing ModelRate itself would silently invalidate every user's existing
// override file. Wire and storage are separate contracts; this is the seam.
type pricingCatalogModel struct {
	ID       string   `json:"id"`
	Provider string   `json:"provider"`
	Aliases  []string `json:"aliases"`
	// Rates are USD per million tokens. The cache rates are nullable: absent
	// means "derive from the input rate using this provider's cache economics"
	// (see pricing.Estimate), which is NOT the same as zero.
	InputPerMTok        float64  `json:"inputPerMTok"`
	OutputPerMTok       float64  `json:"outputPerMTok"`
	CacheReadPerMTok    *float64 `json:"cacheReadPerMTok"`
	CacheWritePerMTok   *float64 `json:"cacheWritePerMTok"`
	CacheWrite1hPerMTok *float64 `json:"cacheWrite1hPerMTok"`
	EffectiveDate       string   `json:"effectiveDate"`
}

// PricingCatalogOutput is the public pricing catalog: entire-api's own
// LiteLLM-drift-checked, validated rate table (internal/pricing), the same one
// ingest prices checkpoints against. This is the canonical source; the CLI's
// embedded pricing/models/*.json and entire.io's /pricing/v1/models.json are
// both meant to mirror it (a release-time export for the former, a caching
// proxy for the latter) rather than maintain independent copies — three
// independently-updated copies of "the same" rates is exactly how the CLI's 1h
// Anthropic cache-write premium went silently missing on one of them.
type PricingCatalogOutput struct {
	// Deploy-cadence data — safe to cache well past a single request. entire.io's
	// proxy is expected to cache this at the edge on top of this header, so this
	// is a floor, not the only caching layer.
	CacheControl string `header:"Cache-Control"`
	Body         struct {
		SchemaVersion int                   `json:"schemaVersion"`
		Models        []pricingCatalogModel `json:"models"`
	}
}

// toPricingCatalogModels maps the internal table onto the wire shape. A nil
// cache rate stays nil (absent, not zero) — Estimate's provider-aware fallback
// depends on that distinction, so flattening it here would change what every
// downstream consumer charges for cached tokens.
func toPricingCatalogModels(models []pricing.ModelRate) []pricingCatalogModel {
	out := make([]pricingCatalogModel, 0, len(models))
	for _, m := range models {
		out = append(out, pricingCatalogModel{
			ID:                  m.ID,
			Provider:            m.Provider,
			Aliases:             m.Aliases,
			InputPerMTok:        m.InputPerMTok,
			OutputPerMTok:       m.OutputPerMTok,
			CacheReadPerMTok:    m.CacheReadPerMTok,
			CacheWritePerMTok:   m.CacheWritePerMTok,
			CacheWrite1hPerMTok: m.CacheWrite1hPerMTok,
			EffectiveDate:       m.EffectiveDate,
		})
	}
	return out
}

// loadPricingCatalogTable loads the embedded pricing table exactly once,
// mirroring internal/ingest/cost.go's loadPricing: a load error means a
// corrupt embedded asset (a build defect, caught by this package's own unit
// tests), not a runtime condition, so it is cached and the endpoint 500s
// rather than crashing the process.
var loadPricingCatalogTable = sync.OnceValues(func() (*pricing.Table, error) {
	return pricing.LoadTable(nil)
})

func registerPricingCatalog(api huma.API) {
	huma.Register(api, huma.Operation{
		OperationID: "pricingCatalog",
		Method:      "GET",
		Path:        apiPrefix + "/pricing/models.json",
		Summary:     "Public pricing catalog",
		Description: "The canonical per-model token rate table, in USD per million tokens. " +
			"Unauthenticated and non-tenant: every model's rate is the same for every caller, " +
			"so this carries no per-user or per-repo gate. Intended for a release-time export " +
			"(the CLI's embedded pricing tables) or a caching proxy (entire.io's " +
			"/pricing/v1/models.json), not direct high-QPS polling — cache the response.",
		Tags: []string{"pricing"},
		// Deliberately no Middlewares: this is public, non-tenant data — see the
		// doc comment above and PricingCatalogOutput's.
	}, func(_ context.Context, _ *struct{}) (*PricingCatalogOutput, error) {
		tbl, err := loadPricingCatalogTable()
		if err != nil {
			return nil, huma.Error500InternalServerError("pricing: load embedded table", fmt.Errorf("%w", err))
		}
		out := &PricingCatalogOutput{CacheControl: "public, max-age=3600"}
		out.Body.SchemaVersion = pricingCatalogSchemaVersion
		out.Body.Models = toPricingCatalogModels(tbl.Models())
		return out, nil
	})
}
