// TestPricingCatalog_WireIsCamelCase is the CASING-001 guard for this route.
// It walks the RAW response rather than a typed struct, because a typed decode
// silently ignores unknown keys — the exact failure mode that would let a
// snake_case field ship unnoticed. Every key at both levels must match
// ^[a-z][a-zA-Z0-9]*$.
//
// This is the one genuinely new public surface in the cost work; the snake_case
// cost fields elsewhere in this package are additive to pre-existing
// snake_case response shapes and stay as they are.
func TestPricingCatalog_WireIsCamelCase(t *testing.T) {
	base := testBase()
	r := NewActivityAPIRouter(&RepoActivityDeps{baseDeps: base}, &UserActivityDeps{baseDeps: base})
	w := httptest.NewRecorder()
	r.HTTPHandler().ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/api/v1/pricing/models.json", nil))
	require.Equal(t, http.StatusOK, w.Code)

	camel := regexp.MustCompile(`^[a-z][a-zA-Z0-9]*$`)

	var envelope map[string]json.RawMessage
	require.NoError(t, json.Unmarshal(w.Body.Bytes(), &envelope))
	require.Contains(t, envelope, "schemaVersion", "envelope must use camelCase schemaVersion")
	for k := range envelope {
		assert.Regexp(t, camel, k, "envelope key %q must be camelCase (CASING-001)", k)
	}

	var models []map[string]json.RawMessage
	require.NoError(t, json.Unmarshal(envelope["models"], &models))
	require.NotEmpty(t, models)
	for _, m := range models {
		for k := range m {
			assert.Regexp(t, camel, k, "model key %q must be camelCase (CASING-001)", k)
		}
	}
}

// TestPricingCatalog_NilCacheRatesStayNull proves the wire mapping preserves
// the absent/zero distinction. Anthropic's embedded entries deliberately carry
// no explicit cache rates so Estimate applies the provider multipliers
// (0.1x read, 1.25x 5-minute write, 2x 1-hour write). Serializing a nil rate
// as 0 would tell every consumer those tokens are free — the same class of
// silent mispricing that motivated making this the single canonical source.
func TestPricingCatalog_NilCacheRatesStayNull(t *testing.T) {
	base := testBase()
	r := NewActivityAPIRouter(&RepoActivityDeps{baseDeps: base}, &UserActivityDeps{baseDeps: base})
	w := httptest.NewRecorder()
	r.HTTPHandler().ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/api/v1/pricing/models.json", nil))
	require.Equal(t, http.StatusOK, w.Code)

	var got struct {
		Models []struct {
			ID                string   `json:"id"`
			Provider          string   `json:"provider"`
			CacheReadPerMTok  *float64 `json:"cacheReadPerMTok"`
			CacheWritePerMTok *float64 `json:"cacheWritePerMTok"`
		} `json:"models"`
	}
	require.NoError(t, json.Unmarshal(w.Body.Bytes(), &got))

	var sawNilAnthropicCacheRate bool
	for _, m := range got.Models {
		if m.Provider == "anthropic" && m.CacheReadPerMTok == nil && m.CacheWritePerMTok == nil {
			sawNilAnthropicCacheRate = true
			break
		}
	}
	assert.True(t, sawNilAnthropicCacheRate,
		"expected at least one anthropic model to serve null cache rates so the provider multipliers apply downstream")
}

// TestToPricingCatalogModels_CarriesEveryField guards the mapper against a
// field being added to pricing.ModelRate and silently not reaching the wire.
func TestToPricingCatalogModels_CarriesEveryField(t *testing.T) {
	read, write, write1h := 0.5, 6.25, 10.0
	got := toPricingCatalogModels([]pricing.ModelRate{{
		ID:                  "claude-opus-4-8",
		Provider:            "anthropic",
		Aliases:             []string{"claude-opus-4-8-*"},
		InputPerMTok:        5,
		OutputPerMTok:       25,
		CacheReadPerMTok:    &read,
		CacheWritePerMTok:   &write,
		CacheWrite1hPerMTok: &write1h,
		EffectiveDate:       "2026-08-25",
	}})

	require.Len(t, got, 1)
	assert.Equal(t, "claude-opus-4-8", got[0].ID)
	assert.Equal(t, "anthropic", got[0].Provider)
	assert.Equal(t, []string{"claude-opus-4-8-*"}, got[0].Aliases)
	assert.InDelta(t, 5.0, got[0].InputPerMTok, 0)
	assert.InDelta(t, 25.0, got[0].OutputPerMTok, 0)
	require.NotNil(t, got[0].CacheReadPerMTok)
	assert.InDelta(t, read, *got[0].CacheReadPerMTok, 0)
	require.NotNil(t, got[0].CacheWritePerMTok)
	assert.InDelta(t, write, *got[0].CacheWritePerMTok, 0)
	require.NotNil(t, got[0].CacheWrite1hPerMTok)
	assert.InDelta(t, write1h, *got[0].CacheWrite1hPerMTok, 0)
	assert.Equal(t, "2026-08-25", got[0].EffectiveDate)
}
